ALTER TABLE public.services ADD COLUMN provider_type text NOT NULL DEFAULT 'Default', ADD COLUMN provider_order_supported boolean NOT NULL DEFAULT true;
CREATE TABLE public.provider_sync_settings(id integer PRIMARY KEY DEFAULT 1 CHECK(id=1), callback_secret text NOT NULL, callback_url text NOT NULL);
GRANT ALL ON public.provider_sync_settings TO service_role;
ALTER TABLE public.provider_sync_settings ENABLE ROW LEVEL SECURITY;
CREATE EXTENSION IF NOT EXISTS pg_cron;
CREATE OR REPLACE FUNCTION public.sync_provider_catalog(_provider uuid,_rows jsonb) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _p public.service_providers; _r jsonb; _platform uuid; _cat uuid; _slug text; _name text; _count integer:=0; BEGIN SELECT * INTO _p FROM public.service_providers WHERE id=_provider AND deleted_at IS NULL FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND'; END IF; UPDATE public.services SET provider_available=false WHERE provider_id=_provider; FOR _r IN SELECT value FROM jsonb_array_elements(_rows) LOOP _slug:=_r->>'platform'; _name:=_r->>'platform_name'; SELECT id INTO _platform FROM public.platforms WHERE slug=_slug; IF _platform IS NULL THEN INSERT INTO public.platforms(slug,name,active) VALUES(_slug,_name,true) RETURNING id INTO _platform; END IF; SELECT id INTO _cat FROM public.categories WHERE platform_id=_platform AND name=_r->>'category' AND deleted_at IS NULL ORDER BY sort LIMIT 1; IF _cat IS NULL THEN INSERT INTO public.categories(platform_id,name,active) VALUES(_platform,_r->>'category',true) RETURNING id INTO _cat; END IF; INSERT INTO public.services(category_id,name,rate,rate_per,min_qty,max_qty,provider_id,provider_service_id,provider_rate,provider_available,provider_type,provider_order_supported) VALUES(_cat,left(_r->>'name',200),ceil((_r->>'rate')::numeric*(1+_p.markup/100)*10000)/10000,1000,(_r->>'min')::integer,(_r->>'max')::integer,_provider,_r->>'service',(_r->>'rate')::numeric,coalesce((_r->>'available')::boolean,true),_r->>'type',lower(_r->>'type')='default') ON CONFLICT(provider_id,provider_service_id) WHERE provider_id IS NOT NULL DO UPDATE SET category_id=EXCLUDED.category_id,name=CASE WHEN services.custom_name THEN services.name ELSE EXCLUDED.name END,rate=CASE WHEN services.custom_rate THEN services.rate ELSE EXCLUDED.rate END,provider_rate=EXCLUDED.provider_rate,min_qty=EXCLUDED.min_qty,max_qty=EXCLUDED.max_qty,provider_available=EXCLUDED.provider_available,provider_type=EXCLUDED.provider_type,provider_order_supported=EXCLUDED.provider_order_supported; _count:=_count+1; END LOOP; UPDATE public.service_providers SET last_synced_at=now() WHERE id=_provider; UPDATE public.site_settings SET content_version=content_version+1 WHERE id=1; RETURN _count; END $$;
REVOKE ALL ON FUNCTION public.sync_provider_catalog(uuid,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.sync_provider_catalog(uuid,jsonb) TO service_role;
CREATE OR REPLACE FUNCTION public.validate_service_source_order() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _s public.services; BEGIN SELECT * INTO _s FROM public.services WHERE id=NEW.service_id; IF NOT public.service_source_enabled(_s.provider_id) OR NOT _s.provider_available THEN RAISE EXCEPTION 'SERVICE_UNAVAILABLE'; END IF; IF _s.provider_id IS NOT NULL AND NOT _s.provider_order_supported THEN RAISE EXCEPTION 'SPECIAL_INPUT_REQUIRED'; END IF; NEW.provider_id:=_s.provider_id; NEW.provider_service_id:=_s.provider_service_id; IF _s.provider_id IS NOT NULL THEN NEW.dispatch_state:='queued'; END IF; RETURN NEW; END $$;